-- Apply after supabase/schema.sql in a new/staging project.
create extension if not exists vector with schema extensions;
create table public.documents (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, product_id uuid, title text not null, source_type text not null check (source_type in ('customer_upload','official_eu','harmonised_standard','notified_body','internal_reviewed')), jurisdiction text not null default 'EU', language text not null default 'en', canonical_url text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), foreign key (tenant_id,product_id) references public.products(tenant_id,id), unique(tenant_id,id));
create table public.document_versions (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, document_id uuid not null, version_label text not null, storage_path text not null, media_type text not null, byte_size bigint not null check(byte_size between 1 and 26214400), sha256 text not null check(sha256 ~ '^[0-9a-f]{64}$'), effective_date date, supersedes_version_id uuid references public.document_versions(id), extraction_status text not null default 'pending' check(extraction_status in ('pending','processing','ready','failed')), created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), foreign key(tenant_id,document_id) references public.documents(tenant_id,id) on delete cascade, unique(tenant_id,document_id,version_label), unique(tenant_id,sha256), unique(tenant_id,id));
create table public.source_approvals (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, document_version_id uuid not null, status text not null check(status in ('pending','approved','rejected','superseded','revoked')), reviewer_id uuid references auth.users(id), rationale text not null default '', reviewed_at timestamptz, foreign key(tenant_id,document_version_id) references public.document_versions(tenant_id,id) on delete cascade, unique(tenant_id,document_version_id));
create table public.document_chunks (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, document_version_id uuid not null, ordinal integer not null, content text not null, heading_path text[] not null default '{}', page_start integer, page_end integer, table_id text, row_start integer, row_end integer, token_count integer not null, content_sha256 text not null, foreign key(tenant_id,document_version_id) references public.document_versions(tenant_id,id) on delete cascade, unique(tenant_id,document_version_id,ordinal), unique(tenant_id,id));
create table public.chunk_embeddings (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, chunk_id uuid not null, model text not null, dimensions integer not null check(dimensions=768), embedding extensions.vector(768) not null, foreign key(tenant_id,chunk_id) references public.document_chunks(tenant_id,id) on delete cascade, unique(tenant_id,chunk_id,model));
create table public.ingestion_jobs (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, document_version_id uuid not null, idempotency_key text not null, status text not null check(status in ('queued','extracting','chunking','embedding','completed','failed')), chunks_total integer not null default 0, chunks_embedded integer not null default 0, attempts integer not null default 0, error_code text, error_detail text, created_by uuid not null references auth.users(id), started_at timestamptz, completed_at timestamptz, foreign key(tenant_id,document_version_id) references public.document_versions(tenant_id,id), unique(tenant_id,idempotency_key));
create table public.answer_citations (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.tenants(id) on delete cascade, chat_message_id uuid references public.chat_messages(id) on delete cascade, chunk_id uuid not null, citation_order integer not null, quoted_text text not null check(length(quoted_text)<=800), retrieval_score real not null check(retrieval_score between 0 and 1), retrieved_at timestamptz not null default now(), foreign key(tenant_id,chunk_id) references public.document_chunks(tenant_id,id));
create index document_chunks_fts_idx on public.document_chunks using gin(to_tsvector('english',content));
create index chunk_embeddings_hnsw_idx on public.chunk_embeddings using hnsw(embedding vector_cosine_ops);
alter table public.documents enable row level security; alter table public.document_versions enable row level security; alter table public.source_approvals enable row level security; alter table public.document_chunks enable row level security; alter table public.chunk_embeddings enable row level security; alter table public.ingestion_jobs enable row level security; alter table public.answer_citations enable row level security;
revoke all on public.documents,public.document_versions,public.source_approvals,public.document_chunks,public.chunk_embeddings,public.ingestion_jobs,public.answer_citations from anon,authenticated;
grant select on public.documents,public.document_versions,public.source_approvals,public.document_chunks,public.ingestion_jobs,public.answer_citations to authenticated;
create policy rag_documents_member_select on public.documents for select to authenticated using(exists(select 1 from public.memberships m where m.tenant_id=documents.tenant_id and m.user_id=(select auth.uid())));
create policy rag_versions_member_select on public.document_versions for select to authenticated using(exists(select 1 from public.memberships m where m.tenant_id=document_versions.tenant_id and m.user_id=(select auth.uid())));
create policy rag_approvals_member_select on public.source_approvals for select to authenticated using(exists(select 1 from public.memberships m where m.tenant_id=source_approvals.tenant_id and m.user_id=(select auth.uid())));
create policy rag_chunks_approved_select on public.document_chunks for select to authenticated using(exists(select 1 from public.memberships m where m.tenant_id=document_chunks.tenant_id and m.user_id=(select auth.uid())) and exists(select 1 from public.source_approvals a where a.tenant_id=document_chunks.tenant_id and a.document_version_id=document_chunks.document_version_id and a.status='approved'));
create policy rag_jobs_member_select on public.ingestion_jobs for select to authenticated using(exists(select 1 from public.memberships m where m.tenant_id=ingestion_jobs.tenant_id and m.user_id=(select auth.uid())));
create policy rag_citations_member_select on public.answer_citations for select to authenticated using(exists(select 1 from public.memberships m where m.tenant_id=answer_citations.tenant_id and m.user_id=(select auth.uid())));
create or replace function public.match_approved_chunks(p_tenant_id uuid,p_query_embedding extensions.vector(768),p_limit integer default 6,p_min_score real default 0.72) returns table(chunk_id uuid,document_version_id uuid,content text,heading_path text[],page_start integer,page_end integer,table_id text,score real) language sql stable security invoker set search_path='' as $$ select c.id,c.document_version_id,c.content,c.heading_path,c.page_start,c.page_end,c.table_id,(1-(e.embedding <=> p_query_embedding))::real from public.document_chunks c join public.chunk_embeddings e on e.tenant_id=c.tenant_id and e.chunk_id=c.id join public.source_approvals a on a.tenant_id=c.tenant_id and a.document_version_id=c.document_version_id and a.status='approved' where c.tenant_id=p_tenant_id and exists(select 1 from public.memberships m where m.tenant_id=p_tenant_id and m.user_id=(select auth.uid())) and (1-(e.embedding <=> p_query_embedding))>=p_min_score order by e.embedding <=> p_query_embedding limit least(greatest(p_limit,1),12) $$;
revoke all on function public.match_approved_chunks(uuid,extensions.vector,integer,real) from public,anon; grant execute on function public.match_approved_chunks(uuid,extensions.vector,integer,real) to authenticated;
